const researchCards=research.map(r=>`<article class="research-card"><div class="research-copy"><span class="index">${r.n} · ${isEn?r.layeren:r.layerzh}</span><h3>${isEn?r.en:r.zh}</h3><p class="en-title">${isEn?r.zh:r.en}</p><p class="summary">${isEn?r.end:r.zhd}</p><div class="publication"><span>${t('代表成果','Featured output')}</span><a href="${r.doi}" target="_blank" rel="noreferrer">${r.paper}</a><small>${r.meta}</small></div></div><figure class="research-figure"><div class="image-stage"><img src="${r.img}" alt="${isEn?r.alten:r.altzh}"></div><figcaption>${t('图：作者','Figure by the authors')}</figcaption></figure></article>`).join('');
const framework=`<section class="framework-section"><div class="framework-heading"><span class="eyebrow">Research framework</span><h2>${t('测量环境，理解人，转译证据','Measure environments, understand people, translate evidence')}</h2><p>${t('我们以古典园林和历史地段为主要验证场景，研究人在移动中如何感知历史环境，并发展环境诊断与设计干预方法。','Using classical gardens and historic districts as principal settings, we study how people perceive historic environments in motion and develop methods for diagnosis and design intervention.')}</p></div><div class="framework-flow" aria-label="${t('三层科研链条','Three-layer research chain')}"><article><span>B · ${t('方法层','Methods')}</span><h3>${t('测量环境','Measure environments')}</h3><p>${t('全景采集 · 视觉识别 · 动态测度 · 三维重建','Panoramic capture · visual recognition · dynamic measurement · 3D reconstruction')}</p></article><i aria-hidden="true">→</i><article><span>A · ${t('机制层','Mechanisms')}</span><h3>${t('理解人','Understand people')}</h3><p>${t('空间感知 · 认知行为 · 路径体验 · 失序机制','Spatial perception · cognition and behaviour · route experience · disorder mechanisms')}</p></article><i aria-hidden="true">→</i><article><span>C · ${t('转译层','Translation')}</span><h3>${t('转译证据','Translate evidence')}</h3><p>${t('失序诊断 · 数字保护 · 沉浸体验 · 设计干预','Disorder diagnosis · digital conservation · immersive experience · design intervention')}</p></article></div><div class="framework-feedback">↺ ${t('真实历史环境问题持续反向驱动方法与机制研究','Problems arising in real historic environments continually drive new method and mechanism studies')}</div></section>`;
const statusOverview=`<section class="status-section"><div class="section-heading"><div><span class="eyebrow">Research development</span><h2>${t('在持续积累中建立研究体系','Building the research system through cumulative work')}</h2></div><p>${t('公开网站区分已经形成的基础、正在推进的工作和需要补充的研究模块，避免把计划表述为成果。','The public site distinguishes established foundations, work in progress, and modules still to be developed, so plans are never presented as completed results.')}</p></div><div class="status-columns"><article class="established"><span>${t('既有基础','Established')}</span><h3>${t('已形成的方法与证据','Methods and evidence in place')}</h3><ul><li>${t('博士论文：全景图像动态视觉信息测度','Doctoral research on panoramic measurement of dynamic visual information')}</li><li>${t('国自然青年基金：园林游观空间感知','NSFC Young Scientists Fund project on garden-tour perception')}</li><li>${t('约10座苏州园林全景图像采集','Panoramic imagery collected in about ten Suzhou gardens')}</li></ul></article><article class="active"><span>${t('当前工作','Current')}</span><h3>${t('正在连接技术与机制','Connecting technology and mechanisms')}</h3><ul><li>${t('语义分割、深度估计与三维重建','Semantic segmentation, depth estimation, and 3D reconstruction')}</li><li>${t('路径变迁与游园感知差异实验','Experiments on route change and garden perception')}</li><li>${t('视觉污染物识别与数字场景原型','Visual-pollutant recognition and digital-scene prototypes')}</li></ul></article><article class="needed"><span>${t('需要补充','To develop')}</span><h3>${t('形成可扩展的研究闭环','Completing a scalable research loop')}</h3><ul><li>${t('视觉失序本体及标注规范','Visual-disorder ontology and annotation standards')}</li><li>${t('客观指标与主观感知的机制桥梁','Mechanistic links between objective metrics and subjective perception')}</li><li>${t('跨场景验证及“诊断—干预—评价”闭环','Cross-setting validation and a diagnosis–intervention–evaluation loop')}</li></ul></article></div></section>`;
const homeScaffold=`<section class="home-about"><div><span class="eyebrow">About us</span><h2>${t('关于我们','About us')}</h2></div><div><p>${t('研究建成环境视觉信息的表征、测度及其与人的感知、认知和行为之间的关系。以移动观察下的动态视觉信息测度为方法特色，融合计算机视觉、三维建模与人因实验，重点关注古典园林和历史地段的视觉体验、失序诊断与循证干预，服务环境品质提升与保护更新。','We investigate the representation and measurement of visual information in built environments and its relationships with human perception, cognition, and behaviour. Our methodological focus is measuring dynamic visual information during movement, integrating computer vision, 3D modelling, and human-factors experiments. With an emphasis on classical gardens and historic districts, we study visual experience, diagnose visual disorder, and develop evidence-based interventions to support environmental quality, conservation, and renewal.')}</p><a class="text-link-inline" href="${prefix}/research/">${t('了解研究框架','Read our research framework')} →</a></div></section><section class="home-feed"><div class="home-section-title"><span class="eyebrow">Updates</span><h2>${t('近期工作','Recent work')}</h2><p>${t('这一栏目将持续记录项目、论文、数据和课题组活动。','This section will grow with projects, papers, data, and group activities.')}</p></div><div class="feed-grid"><article><time>2026.08</time><h3>${t('课题组整体科研框架建立','Research framework established')}</h3><p>${t('形成“测量环境—理解人—转译证据”的三层研究链条。','A three-layer chain now connects environmental measurement, human understanding, and evidence translation.')}</p></article><article><time>2026.08</time><h3>${t('留园数字场景原型','Liuyuan digital-scene prototype')}</h3><p>${t('地空融合 Gaussian Splatting 模型进入网站与沉浸体验原型。','The aerial–ground integrated Gaussian Splatting model enters the website and immersive-experience prototype.')}</p></article><article><time>${t('筹备中','In preparation')}</time><h3>${t('历史环境数据资源','Historic-environment data resources')}</h3><p>${t('采集规范、元数据、权限和公开边界正在建立。','Capture standards, metadata, permissions, and public-release boundaries are being developed.')}</p></article></div></section><section class="home-people"><div class="home-section-title"><span class="eyebrow">People</span><h2>${t('团队','People')}</h2></div><div class="people-preview"><article><span>${t('负责人','Principal investigator')}</span><h3>${t('朱海鹏','Haipeng Zhu')}</h3><p>${t('东南大学建筑学院教师、硕士生导师。','Faculty member and master’s supervisor, School of Architecture, Southeast University.')}</p></article><article><span>${t('课题组成员','Group members')}</span><h3>${t('两名硕士研究生','Two master’s students')}</h3><p>${t('成员信息将在逐项获得公开授权后补充。','Member profiles will be added after field-level public-release consent.')}</p></article><a href="${prefix}/#people">${t('查看团队','Meet the group')} →</a></div></section><section class="home-resources"><div><span class="eyebrow">Data & resources</span><h2>${t('数据与资源','Data & resources')}</h2></div><div><p>${t('逐步建设园林全景、三维场景、视觉失序标注和历史地段数据资源。当前先建立规范与权限层级，再选择可公开内容。','We are developing panoramic garden imagery, 3D scenes, visual-disorder annotations, and historic-district resources. Standards and access levels come before public release.')}</p><a class="text-link-inline" href="${prefix}/projects/">${t('查看建设状态','View development status')} →</a></div></section><section class="home-join"><span class="eyebrow">Join & contact</span><h2>${t('在真实历史环境问题中，连接建筑学、人因研究与计算方法。','Connecting architecture, human-subject research, and computation through real problems in historic environments.')}</h2><a href="${prefix}/join/">${t('招生与合作','Admissions and collaboration')} →</a></section>`;
