const peopleHierarchy=`<div class="people-hierarchy people-flat-grid">${people.map(p=>`<a class="person-tile mentor-card" href="${prefix}/member/${p.slug}/"><img src="${p.photo}" alt="${isEn?p.en:p.zh}"><h3>${isEn?p.en:p.zh}</h3><p>${p.slug==='zhu-haipeng'?t('讲师','Lecturer'):p.slug==='gu-zongchao'?t('副研究员','Associate Research Professor'):t('校外合作研究人员','External Collaborating Researcher')}</p></a>`).join('')}${studentCards.map(studentTile).join('')}<a class="person-tile join-person-card" href="${prefix}/join/" aria-label="${t('加入我们','Join us')}"><span>YOU?</span><h3>${t('你？','You?')}</h3><p>${t('加入我们','Join us')}</p></a></div>`;
