const awardPost=`<article class="post-page"><header class="post-header"><span class="eyebrow">${t('竞赛获奖','Competition award')}</span><h1>${t('《让阿晚留下——油麻地多智能体共生计划》获国际竞赛二等奖','“Let Ah-Wan Stay” receives Second Prize in an international competition')}</h1><p class="post-deck">${t('该作品在2026 WUPENiCity城市设计学生作业国际竞赛中获得二等奖。','The project received Second Prize in the 2026 WUPENiCity International Competition on Students’ Urban Design Works.')}</p><div class="post-meta"><span>${t('建成环境视觉与认知研究组','Built Environment Vision and Cognition Group')}</span><time>2026-05-31</time><span>2 min read</span></div></header><figure class="post-feature"><img src="/news/wupen-let-ah-wan-stay.png" alt="${t('WUPEN获奖作品页面及《让阿晚留下》设计展板','WUPEN award entry and design boards for Let Ah-Wan Stay')}"><figcaption>${t('作品页面与设计展板，来源：WUPEN。','Entry page and design boards. Source: WUPEN.')}</figcaption></figure><div class="post-body"><p>${t('在2026 WUPENiCity城市设计学生作业国际竞赛中，王晓娇负责、纪厚光参与的作品《让阿晚留下——油麻地多智能体共生计划》获得二等奖。作品由朱海鹏、顾宗超指导，参赛单位为香港中文大学建筑学院城市设计理学硕士项目。','“Let Ah-Wan Stay: A Multi-Agent Coexistence Strategy for Yau Ma Tei” received Second Prize in the 2026 WUPENiCity International Competition on Students’ Urban Design Works. The project was led by Xiaojiao Wang with Houguang Ji as team member, supervised by Haipeng Zhu and Zongchao Gu, from the MSc in Urban Design programme at the School of Architecture, The Chinese University of Hong Kong.')}</p><h2>${t('作品简介','About the project')}</h2><p>${t('项目聚焦香港油麻地劏房密集社区在更新过程中面临的原地安置与社区延续问题，以“阿晚”的生活故事为线索，提出多智能体共生系统。循环、呼吸、神经和免疫四类智能体通过“感知—决策—行动”框架协同资源、环境、共生与安全，使居民能够留在熟悉的社区中继续生活。','Focusing on rehousing and community continuity in Yau Ma Tei, one of Hong Kong’s areas with a high concentration of subdivided units, the project follows Ah-Wan’s story and proposes a multi-agent symbiotic system. Four agents—Circulation, Breathing, Neural, and Immune—coordinate resources, environment, coexistence, and safety through a Sense–Decide–Act framework, enabling residents to remain in their familiar neighbourhood.')}</p><h2>${t('参赛信息','Project credits')}</h2><dl class="post-credits"><div><dt>${t('负责人','Lead')}</dt><dd>${t('王晓娇','Xiaojiao Wang')}</dd></div><div><dt>${t('队员','Team member')}</dt><dd>${t('纪厚光','Houguang Ji')}</dd></div><div><dt>${t('指导教师','Supervisors')}</dt><dd>${t('朱海鹏、顾宗超','Haipeng Zhu, Zongchao Gu')}</dd></div><div><dt>${t('参赛单位','Institution')}</dt><dd>${t('香港中文大学建筑学院城市设计理学硕士项目','MSc in Urban Design, School of Architecture, The Chinese University of Hong Kong')}</dd></div></dl><p><a class="post-source" href="http://www.wupen.org/competitions/130?type=work&amp;entry=21402" target="_blank" rel="noopener noreferrer">${t('查看 WUPEN 原始作品页面','View the original WUPEN entry')} →</a></p></div></article>`;
