home:`<section class="home-hero"><div class="home-hero-copy"><div class="hero-kicker">Built Environment Vision and Cognition Group</div><h1 class="${isEn?'':'home-title-zh'}">${t('<span>建成环境</span><span>视觉与认知研究组</span>','Built Environment Vision and Cognition<br><em>Group</em>')}</h1><p>${t('建成环境视觉信息的表征、感知机制与循证干预','Visual information representation, perceptual mechanisms, and evidence-based intervention in built environments')}</p><a class="hero-action" href="#about">${t('了解课题组','Discover the group')} <span>↓</span></a></div><figure class="home-hero-visual"><video autoplay muted loop playsinline preload="metadata" poster="/home/liuyuan-gaussian-splatting-poster.jpg" aria-label="${t('留园地空融合 Gaussian Splatting 三维模型漫游','Fly-through of the Liuyuan aerial–ground integrated Gaussian Splatting model')}"><source src="/home/liuyuan-gaussian-splatting-homepage-v1.mp4" type="video/mp4">${t('您的浏览器不支持视频播放。','Your browser does not support HTML video.')}</video><figcaption>${t('留园地空融合 Gaussian Splatting 三维模型','Aerial–ground integrated Gaussian Splatting model of Liuyuan Garden')}</figcaption></figure></section>${ualHome}`,
